const body = $input.item.json.body || $input.item.json;
const events = Array.isArray(body) ? body : [body];
const event = events[0] || {};
const props = (event.properties && typeof event.properties === 'object') ? event.properties : {};
function pv(v){ return (v && typeof v === 'object' && 'value' in v) ? v.value : v; }
const dealId = String(event.objectId || event.dealId || event.id || event.hs_object_id || event.objectid || pv(props.hs_object_id) || pv(props.dealId) || '');
if (!dealId) throw new Error('No deal ID in webhook payload');
const subscriptionType = event.subscriptionType || 'deal.creation';
const occurredAt = new Date(event.occurredAt || Date.now());
const triggerLabel = subscriptionType === 'deal.propertyChange' ? 'Webhook: Stage Changed' : 'Webhook: Deal Created';
const sevenDaysAgo = new Date(occurredAt.getTime() - 7 * 24 * 60 * 60 * 1000);
return [{ json: {
  dealId,
  portalId: String(event.portalId || 'REPLACE_WITH_PORTAL_ID'),
  subscriptionType,
  triggerLabel,
  occurredAt: occurredAt.toISOString(),
  avomaFrom: sevenDaysAgo.toISOString().split('T')[0],
  avomaTo: occurredAt.toISOString().split('T')[0],
  forceRescreen: !!(event.forceRescreen || body.forceRescreen)
} }];

// v3.9.7 - Build an Avoma query from documented, safe server-side filters.
const d = $input.item.json || {};

function arr(v) { return Array.isArray(v) ? v : []; }
function uniq(values) {
  return [...new Set(values.map(v => String(v || '').trim()).filter(Boolean))];
}
function validDate(value) {
  const dt = value ? new Date(value) : null;
  return dt && !Number.isNaN(dt.getTime()) ? dt : null;
}
function startOfUtcDay(value) {
  const dt = validDate(value);
  if (!dt) return null;
  return new Date(Date.UTC(dt.getUTCFullYear(), dt.getUTCMonth(), dt.getUTCDate(), 0, 0, 0, 0));
}
function endOfUtcDay(value) {
  const dt = validDate(value);
  if (!dt) return null;
  return new Date(Date.UTC(dt.getUTCFullYear(), dt.getUTCMonth(), dt.getUTCDate(), 23, 59, 59, 999));
}

const occurredAt = validDate(d.occurredAt) || new Date();
const fallbackFrom = startOfUtcDay(d.avomaFrom) || new Date(occurredAt.getTime() - 7 * 24 * 60 * 60 * 1000);
const fallbackTo = endOfUtcDay(d.avomaTo) || occurredAt;
const noteDates = arr(d.noteTimestamps).map(validDate).filter(Boolean);
const dateCandidates = [validDate(d.dealCreatedAt), ...noteDates, fallbackFrom].filter(Boolean);
const fromDate = new Date(Math.min(...dateCandidates.map(dt => dt.getTime()))).toISOString();
const toDate = new Date(Math.max(occurredAt.getTime(), fallbackTo.getTime(), Date.now())).toISOString();

const dealIds = uniq([d.dealId]);
const companyIds = uniq(arr(d.companyIds));
const contactIds = uniq(arr(d.contactIds));
const contactEmails = uniq(arr(d.contactEmails).map(e => String(e).toLowerCase()));
const companies = arr(d.companies);
const companyDomains = uniq([
  ...arr(d.companyDomains),
  ...companies.map(c => c && c.domain),
]).map(x => x.toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0]);
const companyNames = uniq([
  d.companyName,
  ...companies.map(c => c && c.name),
]);

function createQueryParams(params) {
  return Object.entries(params)
    .filter(([key, value]) => value !== undefined && value !== null && value !== '')
    .map(([key, value]) => `${encodeURIComponent(key)}=${encodeURIComponent(value)}`)
    .join('&');
}

const params = createQueryParams({
  from_date: fromDate,
  to_date: toDate,
  page_size: '100',
  include_crm_associations: 'true',
  o: '-start_at',
  crm_opportunity_ids: dealIds.length ? dealIds.join(',') : undefined,
  crm_account_ids: companyIds.length ? companyIds.join(',') : undefined,
  crm_contact_ids: contactIds.length ? contactIds.join(',') : undefined,
  attendee_emails: contactEmails.length ? contactEmails.join(',') : undefined,
});

const searchSignals = [];
if (dealIds.length) searchSignals.push('crm_opportunity_ids');
if (companyIds.length) searchSignals.push('crm_account_ids');
if (contactIds.length) searchSignals.push('crm_contact_ids');
if (contactEmails.length) searchSignals.push('attendee_emails');
if (companyDomains.length) searchSignals.push('company_domains_for_scoring');
if ((d.ownerEmail || '').trim()) searchSignals.push('owner_email_for_scoring');
if (companyNames.length) searchSignals.push('company_name_for_scoring');

const avomaShouldQuery = dealIds.length > 0 || companyIds.length > 0 || contactIds.length > 0 || contactEmails.length > 0;

return [{ json: {
  ...d,
  dealCreatedAt: d.dealCreatedAt || '',
  noteTimestamps: arr(d.noteTimestamps),
  companyDomains,
  avomaQueryString: params,
  avomaFromDateTime: fromDate,
  avomaToDateTime: toDate,
  avomaShouldQuery,
  avomaSearchSignals: searchSignals,
  avomaCompanyNames: companyNames,
  avomaCompanyDomains: companyDomains,
  avomaDealName: d.dealname || '',
  avomaSearchAttempted: false,
  avomaSkipped: !avomaShouldQuery,
  avomaSkipReason: avomaShouldQuery ? '' : 'No safe Avoma search signals',
  hasMeetings: false,
  meetingCount: 0,
  avomaRelevantMeetingCount: 0,
  avomaMeetings: [],
  avomaNotesContext: '',
  avomaTranscriptContext: '',
  avomaMatchReasons: []
} }];

// v3.9.3 - Score all returned Avoma meetings and keep every relevant call.
const deal = $('Build Avoma Query').item.json || {};
const inputItems = $input.all();

function arr(v) { return Array.isArray(v) ? v : []; }
function norm(v) { return String(v || '').trim().toLowerCase(); }
function uniq(values) { return [...new Set(values.map(v => String(v || '').trim()).filter(Boolean))]; }
function textIncludes(haystack, needle) {
  const h = norm(haystack);
  const n = norm(needle);
  return !!n && h.includes(n);
}
function emailDomain(email) {
  const e = norm(email);
  const at = e.lastIndexOf('@');
  return at >= 0 ? e.slice(at + 1) : '';
}
function getMeetingDate(m) {
  const dt = new Date(m.start_at || m.date || m.created_at || m.created || 0);
  return Number.isNaN(dt.getTime()) ? 0 : dt.getTime();
}
function extractMeetings(payload) {
  if (!payload) return [];
  if (Array.isArray(payload)) return payload.flatMap(extractMeetings);
  const body = payload.body || payload;
  if (Array.isArray(body)) return body.flatMap(extractMeetings);
  if (Array.isArray(body.results)) return body.results;
  if (Array.isArray(body.data)) return body.data;
  return [];
}

const meetings = inputItems.flatMap(item => extractMeetings(item.json));
const apiErrored = inputItems.some(item => {
  const j = item.json || {};
  return !!(j.error || j.detail || (j.statusCode && Number(j.statusCode) >= 400));
});

const dealIds = uniq([deal.dealId]);
const companyIds = uniq(arr(deal.companyIds));
const contactIds = uniq(arr(deal.contactIds));
const contactEmails = uniq(arr(deal.contactEmails).map(norm));
const companyDomains = uniq(arr(deal.companyDomains).map(norm));
const companyNames = uniq([...(arr(deal.avomaCompanyNames)), deal.companyName].map(norm));
const dealName = norm(deal.avomaDealName || deal.dealname);
const ownerEmail = norm(deal.ownerEmail);

function crmScore(m) {
  let score = 0;
  const reasons = [];
  const assocs = arr(m.crm_associations);
  for (const assoc of assocs) {
    const id = String(assoc.crm_obj_id || assoc.id || '').trim();
    const type = norm(assoc.crm_obj_type || assoc.type || '');
    if (dealIds.includes(id) && ['oppo', 'opportunity', 'deal'].includes(type)) {
      score += 10; reasons.push('crm_opportunity_match');
    } else if (companyIds.includes(id) && ['account', 'company'].includes(type)) {
      score += 7; reasons.push('crm_account_match');
    } else if (contactIds.includes(id) && type === 'contact') {
      score += 6; reasons.push('crm_contact_match');
    }
  }
  return { score, reasons };
}

function scoreMeeting(m) {
  let score = 0;
  const reasons = [];
  const title = m.subject || m.title || m.name || '';
  const attendees = arr(m.attendees).length ? arr(m.attendees) : arr(m.participants);
  const attendeeEmails = uniq(attendees.map(a => norm(a.email || a.email_address || a.user_email)));
  const attendeeDomains = uniq(attendeeEmails.map(emailDomain));

  const crm = crmScore(m);
  score += crm.score; reasons.push(...crm.reasons);

  if (contactEmails.length && attendeeEmails.some(e => contactEmails.includes(e))) {
    score += 5; reasons.push('attendee_email_match');
  }
  if (companyDomains.length && attendeeDomains.some(d => companyDomains.includes(d))) {
    score += 4; reasons.push('company_domain_attendee');
  }
  if (companyNames.some(name => textIncludes(title, name))) {
    score += 3; reasons.push('company_name_in_subject');
  }
  if (dealName && !companyNames.includes(dealName) && textIncludes(title, dealName)) {
    score += 2; reasons.push('deal_name_in_subject');
  }
  if (ownerEmail && norm(m.organizer_email) === ownerEmail) {
    score += 2; reasons.push('organizer_is_deal_owner');
  }
  if (m.state === 'completed' || m.transcript_ready === true || m.transcription_uuid) {
    score += 1; reasons.push('completed_or_transcript_ready');
  }

  return { score, reasons: uniq(reasons) };
}

const relevant = meetings
  .map(m => {
    const scored = scoreMeeting(m);
    const meetingUuid = m.uuid || m.meeting_uuid || '';
    const transcriptionUuid = m.transcription_uuid || m.transcription || m.transcriptionUuid || '';
    return {
      uuid: meetingUuid,
      meetingUuid,
      transcriptionUuid,
      subject: m.subject || m.title || m.name || '',
      start_at: m.start_at || m.date || m.created_at || m.created || '',
      organizer_email: m.organizer_email || '',
      state: m.state || '',
      transcript_ready: m.transcript_ready === true,
      notes_ready: m.notes_ready === true,
      attendees: arr(m.attendees).map(a => ({ email: a.email || a.email_address || '', name: a.name || '' })),
      crm_associations: arr(m.crm_associations),
      score: scored.score,
      reasons: scored.reasons,
      raw: m,
    };
  })
  .filter(m => m.score > 0 && m.meetingUuid)
  .sort((a, b) => (b.score - a.score) || (getMeetingDate(b) - getMeetingDate(a)));

const reasonSummary = relevant.flatMap(m => m.reasons);
const first = relevant[0] || {};

return [{ json: {
  ...deal,
  avomaSearchAttempted: true,
  avomaSkipped: false,
  avomaSkipReason: '',
  avomaApiErrored: apiErrored,
  hasMeetings: relevant.length > 0,
  meetingCount: meetings.length,
  avomaRelevantMeetingCount: relevant.length,
  avomaMeetings: relevant,
  avomaMatchReasons: uniq(reasonSummary),
  meetingTitle: first.subject || '',
  transcriptionUuid: first.transcriptionUuid || null,
  meetingSummary: '',
  hasTranscript: false,
} }];

const input = $input.item.json || {};
let deal = input;
if (!Object.prototype.hasOwnProperty.call(deal, 'hasMeetings')) {
  try { deal = $('Aggregate Avoma Context').item.json; }
  catch (e) {
    try { deal = $('Score Relevant Meetings').item.json; }
    catch (e2) { deal = input; }
  }
}
const trans = input;
const countries = [deal.countries_onboarding, deal.countries_to_be_on_boarded].filter(Boolean).join(', ') || 'unknown';
const jobTitles = (deal.jobTitles || []).join(', ') || 'unknown';
const contactLines = (deal.contacts || []).map(c => `${[c.firstName,c.lastName].filter(Boolean).join(' ') || c.email || c.id} - ${c.jobtitle || 'unknown title'} - ${c.email || 'no email'}`).join('\n') || 'No associated contacts found.';
const mapping = deal.industryMapping || {};
const candidates = (mapping.candidate_rows || []).slice(0, 10).map((r, i) => `${i + 1}. ${r.hubspot_industry} | NAICS ${r.naics_code} | ${r.industry_label} | source=${r.source}${r.score !== null && r.score !== undefined ? ' | score=' + r.score : ''}`).join('\n') || '(no mapping candidates)';
const overview = `DEAL OVERVIEW
=============
Deal: ${deal.dealname} (ID: ${deal.dealId})
Company Context: ${deal.companyIndustryContext || 'No associated company context.'}
Trigger: ${deal.triggerLabel}
Stage: ${deal.enteredStageName}
Deal Owner: ${deal.ownerFullName || deal.ownerName || 'unknown'}${deal.ownerEmail || deal.repEmail ? ' <' + (deal.ownerEmail || deal.repEmail) + '>' : ''}
Target Countries: ${countries}
Deal Industry Field: ${deal.deal_industry || deal.rawDealIndustry || 'unknown'}
Selected Industry: ${deal.industry || 'not set'}
Selected NAICS Code: ${deal.naics_code || 'not set'}
Contact / Title Data:
${contactLines}
Job Titles Summary: ${jobTitles}
Amount: ${deal.amount ? '$'+deal.amount : 'unknown'}
Goals: ${deal.business_goals || '(not set)'}
Next Steps: ${deal.hs_next_step || '(not set)'}
Decision Process: ${deal.decision_process || '(not set)'}
Decision Criteria: ${deal.decision_criteria || '(not set)'}`;
const sourceHandling = `

SOURCE INDUSTRY HANDLING
========================
If Deal Industry Field is blank and Company Context includes an associated company industry, treat the associated company industry as the primary source. Preserve that literal value in human-readable outputs. Do not replace MUSIC/Media with a NAICS-derived label such as Museums. NAICS is supporting evidence only, not the human-facing source industry.`;
const mappingSection = `

INDUSTRY MAPPING EVIDENCE
=========================
Source files: ${(mapping.source_files || []).join(', ') || 'none'}
Match Method: ${mapping.match_method || 'none'}
Mapping Confidence: ${mapping.mapping_confidence || 'none'}
Mapped HubSpot Industry: ${mapping.mapped_hubspot_industry || 'none'}
Mapped NAICS Code: ${mapping.mapped_naics_code || 'none'}
Mapped 2-Digit NAICS: ${mapping.mapped_naics_2_digit || 'none'}
Mapped Industry Label: ${mapping.mapped_industry_label || 'none'}
Candidate Rows:
${candidates}`;
const notesSection = `

DEAL NOTES
==========
${deal.notesContext || '(no notes yet)'}`;

let avomaStatus = 'Not searched.';
if (deal.avomaSkipped) {
  avomaStatus = `Skipped - ${deal.avomaSkipReason || 'no safe Avoma search signals'}.`;
} else if (deal.avomaSearchAttempted && (deal.avomaRelevantMeetingCount || 0) > 0) {
  avomaStatus = `Searched ${deal.avomaFromDateTime || deal.avomaFrom || ''} to ${deal.avomaToDateTime || deal.avomaTo || ''}; ${deal.avomaRelevantMeetingCount} relevant meeting(s) found from ${deal.meetingCount || deal.avomaRelevantMeetingCount} returned. Signals: ${(deal.avomaSearchSignals || []).join(', ') || 'none'}. Match reasons: ${(deal.avomaMatchReasons || []).join(', ') || 'none'}.`;
} else if (deal.avomaSearchAttempted) {
  avomaStatus = `Searched ${deal.avomaFromDateTime || deal.avomaFrom || ''} to ${deal.avomaToDateTime || deal.avomaTo || ''}; no relevant meetings found. Signals: ${(deal.avomaSearchSignals || []).join(', ') || 'none'}.`;
}

const avomaSection = `

AVOMA SEARCH
============
${avomaStatus}

${deal.avomaNotesContext || (deal.hasMeetings ? 'No Avoma AI notes returned for relevant meetings.' : '')}`.trimEnd();

let transcriptSection = '\n\nTRANSCRIPT: Not available.';
if (deal.avomaTranscriptContext) {
  transcriptSection = `\n\n${deal.avomaTranscriptContext}`;
} else if (!trans?.error && Array.isArray(trans?.transcript)) {
  const speakerMap = {};
  for (const s of (trans.speakers || [])) speakerMap[s.id] = { name: s.name || 'Unknown', isRep: s.is_rep || false };
  let txt = '', chars = 0;
  for (const seg of trans.transcript) {
    const sp = speakerMap[seg.speaker_id] || { name: 'Unknown', isRep: false };
    const line = `${sp.isRep ? '[REP]' : '[PROSPECT]'} ${sp.name}: ${seg.transcript || seg.text || ''}\n`;
    if (chars + line.length > 6000) break;
    txt += line; chars += line.length;
  }
  transcriptSection = `\n\nTRANSCRIPT: ${deal.meetingTitle}\n${'='.repeat(50)}\n${txt || 'No transcript text returned.'}`;
}
return [{ json: { ...deal, contextBlock: overview + sourceHandling + mappingSection + notesSection + '\n\n' + avomaSection + transcriptSection, hasTranscript: !!(deal.hasTranscript || (Array.isArray(trans?.transcript) && !trans?.error)) } }];

// ─────────────────────────────────────────────────────────────────────────────
// ATLAS SECTOR MATRIX ENGINE v5.1 — transcribed from the EOR Compliance Criteria
// One-Sheeter (Atlas OHS WSE and EOR Entity Risk Guide V3). Deterministic.
// v5.1: alias resolution (fixes "E-Learning" et al.), never-blank fallback,
//       concise single-line verdict for notes.
// Call: atlasEvaluate({ aiSector, aiIndustry, aiTier, naics, hasTitle, gate1, gate2 })
// ─────────────────────────────────────────────────────────────────────────────

const ATLAS_SECTORS = [
  { id: 0,  name: 'Professional / Office / Technology (general)', naics: ['5112','5132','5151','5182','5191','5415','5416','5418','5411','5613','5614','5615','5121','5122','5179','5174','5417'], tier: 1, mixed: false, screen_out: false, addendum: 'No', note: 'Desk-based, remote, non-regulated office work: software, SaaS, IT services, marketing, advertising, design, media/publishing, e-learning, HR tech, recruiting (office), consulting, non-regulated finance back-office, legal tech.' },
  { id: 1,  name: 'Teleworkers / Homeworkers', naics: ['5616'], tier: 1, mixed: false, screen_out: false, addendum: 'No', note: 'Remote/home-based roles.' },
  { id: 2,  name: 'Construction & Civil Engineering', naics: ['236','237','238'], tier: 2, mixed: false, screen_out: false, addendum: 'Usually Yes', note: 'On-site construction.' },
  { id: 3,  name: 'Manufacturing & Industrial Plants', naics: ['311','313','314','315','316','321','322','323','324','326','331','332','333','334','335','336','337','338','339'], tier: 2, mixed: false, screen_out: false, addendum: 'Usually Yes', note: 'Plant/line work.' },
  { id: 4,  name: 'Laboratories (Chemical/Bio/Pharma)', naics: ['325'], tier: 2, mixed: true, screen_out: false, addendum: 'Usually Yes', note: 'MIXED: T2 general; T3 GMP/GxP-regulated.' },
  { id: 5,  name: 'Warehousing, Logistics & Distribution', naics: ['493','484'], tier: 2, mixed: true, screen_out: false, addendum: 'Usually Yes', note: 'MIXED: T2 general; T3 unionized/CBA ops.' },
  { id: 6,  name: 'Energy, Utilities & Data Centres', naics: ['2211','2212','2213'], tier: 2, mixed: true, screen_out: false, addendum: 'Usually Yes', note: 'MIXED: T2 non-nuclear; T3 nuclear.' },
  { id: 7,  name: 'Marine, Offshore & Oil and Gas', naics: ['211','213','483','4861','4862'], tier: 3, mixed: false, screen_out: true, addendum: 'N/A', note: 'Oil/gas extraction, offshore/maritime operations.' },
  { id: 8,  name: 'Healthcare & Clinical Settings', naics: ['621','622','623'], tier: 2, mixed: true, screen_out: false, addendum: 'Usually Yes', note: 'MIXED: T3 licensed clinical; T2 admin/back-office.' },
  { id: 9,  name: 'Security & Armed Guarding', naics: ['561612'], tier: 3, mixed: false, screen_out: true, addendum: 'N/A', note: 'Armed/guarding security.' },
  { id: 11, name: 'Heavy Engineering / Mining', naics: ['212','2131'], tier: 2, mixed: false, screen_out: false, addendum: 'Usually Yes', note: 'Mining/heavy engineering.' },
  { id: 12, name: 'Agriculture, Forestry & Fishing', naics: ['111','112','113','114','115'], tier: 2, mixed: false, screen_out: false, addendum: 'Usually Yes', note: 'Field agriculture/forestry/fishing.' },
  { id: 13, name: 'Waste Management & Recycling', naics: ['562'], tier: 2, mixed: false, screen_out: false, addendum: 'Usually Yes', note: 'Waste/recycling ops.' },
  { id: 14, name: 'Hospitality / Large Industrial Kitchens', naics: ['721','722'], tier: 2, mixed: false, screen_out: false, addendum: 'Sometimes', note: 'Hospitality, kitchens.' },
  { id: 15, name: 'Education — Special Needs / Boarding', naics: ['6111','6112','6113'], tier: 2, mixed: true, screen_out: false, addendum: 'Sometimes', note: 'MIXED: T3 regulated teaching; T2 support.' },
  { id: 16, name: 'Retail', naics: ['44','45'], tier: 2, mixed: true, screen_out: false, addendum: 'Sometimes', note: 'MIXED: T1 corporate/e-comm office; T2 store/warehouse.' },
  { id: 17, name: 'Aviation, Transportation & Passenger Services', naics: ['481','485','4811','4812'], tier: 2, mixed: true, screen_out: false, addendum: 'Usually Yes', note: 'MIXED: T3 crew/pilots/ATC; T2/T1 back office.' },
  { id: 18, name: 'Bitcoin / Cryptocurrency & Online Payments', naics: ['523130','5223','522320'], tier: 2, mixed: false, screen_out: false, addendum: 'Sometimes', note: 'Crypto/payments.' },
  { id: 19, name: 'Alcohol and Tobacco', naics: ['312'], tier: 2, mixed: true, screen_out: false, addendum: 'Usually Yes', note: 'MIXED: T2 general; T3 regulated production.' },
  { id: 20, name: 'Non-Profit Organizations', naics: ['813'], tier: 2, mixed: true, screen_out: false, addendum: 'Usually Yes', note: 'MIXED: T2 general; T3 Political & Religious.' },
  { id: 21, name: 'Financial Services & Insurance', naics: ['522','523','524'], tier: 2, mixed: true, screen_out: false, addendum: 'Usually Yes', note: 'MIXED: T2 general; T3 regulated roles (trading, fund mgmt, broker, licensed control).' },
  { id: 22, name: 'Tax & Accounting', naics: ['5412'], tier: 2, mixed: true, screen_out: false, addendum: 'Usually Yes', note: 'MIXED: T2 general; T3 licensed/regulated.' },
  { id: 23, name: 'Arms / Military Related', naics: ['9711','332992','332994','336414','336415'], tier: 3, mixed: false, screen_out: true, addendum: 'N/A', note: 'Arms/military.' },
  { id: 24, name: 'Adult Entertainment', naics: [], tier: 3, mixed: false, screen_out: true, addendum: 'N/A', note: 'All roles screened out.' },
  { id: 25, name: 'Customs Brokerage & Freight Forwarding (licensed)', naics: ['488510'], tier: 3, mixed: false, screen_out: true, addendum: 'N/A', note: 'Licensed customs brokerage.' },
  { id: 27, name: 'Building Materials Manufacturing', naics: ['327'], tier: 3, mixed: false, screen_out: true, addendum: 'N/A', note: 'Building materials mfg (hazardous).' },
  // "Medical Professions" (#28) and "Financial Regulated Roles" (#26) are the role-driven
  // Tier-3 branch of their mixed parents (Healthcare, Financial) — handled via Gate 2 / sub-tier,
  // NOT as NAICS sectors (their codes overlap, which wrongly forced admin staff to Tier 3).
  { id: 29, name: 'Maritime Pilots / Harbor Authority Roles', naics: ['4883'], tier: 3, mixed: false, screen_out: true, addendum: 'N/A', note: 'Maritime pilots/harbor authority.' },
  { id: 30, name: 'Sensitive Data / Security-Cleared Work', naics: ['9281','928'], tier: 3, mixed: false, screen_out: true, addendum: 'N/A', note: 'Sensitive/security-cleared/classified.' },
];

const SECTOR_BY_NAME = {};
for (const s of ATLAS_SECTORS) SECTOR_BY_NAME[s.name.toLowerCase()] = s;
const SECTOR_BY_ID = {};
for (const s of ATLAS_SECTORS) SECTOR_BY_ID[s.id] = s;

// Alias resolution — maps messy real-world industry labels onto a canonical sector id.
// Ordered: high-risk & specific FIRST, the Tier-1 office/tech catch-all LAST. First match wins.
const SECTOR_ALIASES = [
  [/(arms|military|defen[cs]e|weapon|munition|firearm|ammunition)/i, 23],
  [/(adult entertainment|pornograph|escort|strip club)/i, 24],
  [/(customs broker|freight forward)/i, 25],
  [/(building material|cement|concrete|gypsum|glass manufactur|nonmetallic mineral|aerogel|insulation manufactur)/i, 27],
  [/(maritime pilot|harbou?r authorit)/i, 29],
  [/(security clear|classified|sensitive data|national security|defense-?sensitive|export control)/i, 30],
  [/(armed guard|security guard|guarding service|private security)/i, 9],
  [/(oil|gas|petroleum|offshore|drilling|upstream|oilfield|\blng\b|seismic|stratigraph|energy.*services|marine.*(oil|energy)|shipping line)/i, 7],
