  [/(waste|recycl|sanitation|scrap)/i, 13],
  [/(hospitalit|\bhotel|restaurant|catering|industrial kitchen|food service|\bqsr\b)/i, 14],
  [/(laborator|chemical manufactur|biotech.*(lab|manufactur)|pharma.*manufactur|\bgmp\b|\bgxp\b|reagent)/i, 4],
  [/(nuclear|utilit|power generation|electric power|power plant|data cent(er|re)|grid operator)/i, 6],
  [/(aviation|airline|airport|aerospace|passenger transport|\brail\b|train operator|maritime crew|cruise)/i, 17],
  [/(alcohol|brewer|winer|distiller|tobacco|cannabis|vape)/i, 19],
  [/(non-?profit|\bngo\b|charit|foundation|religious|political|advocacy)/i, 20],
  [/(hospital|clinic|patient|nursing|medical (center|centre|practice|device)|health ?care|elder ?care|home ?care|dental|veterinar)/i, 8],
  [/(\bbank|insurance|financial servic|payment|investment|asset management|broker|trading|capital markets|lending|credit union|wealth management|\betf|fund manager|securities)/i, 21],
  [/(\btax\b|accounting|\baudit|bookkeep)/i, 22],
  [/(retail|e-?commerce|ecommerce|consumer goods|merchandis|\bstore\b|\bshop\b|apparel|fashion brand)/i, 16],
  [/(special needs|boarding school|k-?12|primary school|secondary school|licensed teach)/i, 15],
