  // Tier-1 office / tech / professional — catch-all, LAST.
  [/(e-?learning|ed-?tech|education technology|online (education|learning|course|subscription)|ebook|e-?book|software|\bsaas\b|internet|information technology|\bit\b services|computer|technolog|marketing|advertis|\bmedia\b|publish|broadcast|podcast|\bfilm\b|music|creative|design|consult|business services|professional services|human resources|\bhr\b|staffing|recruit|legal tech|telecom|digital|web\b|platform|analytics|fintech|financial technology|research|think tank|data\b)/i, 0],
];

function sectorFromAlias(text) {
  const t = String(text || '');
  if (!t.trim()) return null;
  for (const [re, id] of SECTOR_ALIASES) { if (re.test(t)) return SECTOR_BY_ID[id]; }
  return null;
}

function _digits(v) { return String(v == null ? '' : v).replace(/\D/g, ''); }

function sectorFromNaics(naics) {
  const code = _digits(naics);
  if (!code) return null;
  let best = null, bestLen = 0;
  for (const s of ATLAS_SECTORS) {
    for (const p of s.naics) {
      if (code.startsWith(p) && p.length > bestLen) { best = s; bestLen = p.length; }
    }
  }
  return best;
}

// Resolve a sector from a free-text label: exact canonical → alias table → fuzzy contains.
function sectorFromName(name) {
  const raw = String(name || '').trim();
  const n = raw.toLowerCase();
  if (!n) return null;
  if (SECTOR_BY_NAME[n]) return SECTOR_BY_NAME[n];
  const alias = sectorFromAlias(raw);
  if (alias) return alias;
  for (const s of ATLAS_SECTORS) {
    const sn = s.name.toLowerCase();
    if (sn.includes(n) || n.includes(sn.split(' (')[0])) return s;
  }
  return null;
}

function tierStr(n) {
  if (n === 1) return 'Tier 1';
  if (n === 2) return 'Tier 2';
  if (n === 3) return 'Tier 3';
  return 'Insufficient Data';
}

function atlasEvaluate(opts) {
  const aiSector = opts.aiSector || '';
  const aiIndustry = opts.aiIndustry || '';
  const aiTier = [1, 2, 3].includes(opts.aiTier) ? opts.aiTier : null;
  const naics = opts.naics || '';
  const hasTitle = !!opts.hasTitle;
  const gate1 = opts.gate1 || {};
  const gate2 = opts.gate2 || {};

  // 1) Resolve from NAICS + sector label + industry label; take HIGHER-RISK match.
  const naicsSector = sectorFromNaics(naics);
  const nameSector = sectorFromName(aiSector) || sectorFromName(aiIndustry);
  function riskRank(s) { return s ? (s.screen_out ? 4 : s.tier) : -1; }
  let sector, resolvedBy, unrecognizedLabel = false;
  if (naicsSector && nameSector) {
    if (riskRank(nameSector) > riskRank(naicsSector)) { sector = nameSector; resolvedBy = 'industry label (higher-risk than NAICS)'; }
    else { sector = naicsSector; resolvedBy = 'NAICS code'; }
  } else if (naicsSector || nameSector) {
    sector = naicsSector || nameSector;
    resolvedBy = naicsSector ? 'NAICS code' : 'industry label';
  } else if (String(aiSector || aiIndustry).trim()) {
    sector = SECTOR_BY_ID[0];
    resolvedBy = 'unrecognized label → review';
    unrecognizedLabel = true;
  }

  // Truly unplaceable -> Insufficient ONLY when NOTHING named a sector.
  if (!sector) {
    return {
      tier: 'Insufficient Data', eorCompliant: 'Pending', screenRequired: 'Yes',
      preliminaryFlag: gate1.entityInCountry ? 'Flag: Legal Entity Conflict' : (gate1.exec ? 'Flag: Executive Role' : 'Cleared - Move to Sector Assessment'),
      sectorId: null, sectorName: '(no sector signal)', resolvedBy: 'none',
      basis: 'Insufficient Data — no industry, NAICS, company description, or deal-name signal identified a sector. Add an industry/company detail to re-screen.',
      screenOutTrigger: '', confidence: 'low', needsTitle: false, unplaceable: true, unrecognizedLabel: false,
    };
  }

  // Unrecognized-but-named label -> Tier 2 review (never blank).
  if (unrecognizedLabel) {
    let pf = 'Cleared - Move to Sector Assessment';
    if (gate1.entityInCountry) pf = 'Flag: Legal Entity Conflict'; else if (gate1.exec) pf = 'Flag: Executive Role';
    const label = String(aiSector || aiIndustry).trim();
    return {
      tier: 'Tier 2', eorCompliant: 'Pending', screenRequired: 'Yes',
      preliminaryFlag: pf, sectorId: null, sectorName: label, resolvedBy,
      basis: `Tier 2 — industry "${label}" did not match a known Atlas sector; routed to manual sector confirmation.`,
      screenOutTrigger: '', confidence: 'low', needsTitle: false, unplaceable: false, unrecognizedLabel: true,
    };
  }

  // 2) Gate 2 hard screens -> Tier 3.
  let tier = sector.tier;
  let screenOutTrigger = '';
  if (sector.screen_out) { tier = 3; screenOutTrigger = `Hard screen-out sector: ${sector.name}`; }
  if (gate2.entityLicense) { tier = 3; screenOutTrigger = screenOutTrigger || 'Role requires employer-held sector license/certification'; }
  if (gate2.individualLicense) { tier = 3; screenOutTrigger = screenOutTrigger || 'Non-portable individual license tied to employer entity'; }
  if (gate2.unionCba) { tier = 3; screenOutTrigger = screenOutTrigger || 'Union/CBA requires the operating company to employ directly'; }
  if (gate2.sensitiveSecurity) { tier = 3; screenOutTrigger = screenOutTrigger || 'Sensitive data / security-clearance / classified work'; }

  // 3) Mixed sectors: role sub-tier from title; else Tier 2 + needs-title.
  let needsTitle = false;
  let confidence;
  if (tier !== 3 && sector.mixed) {
    if (hasTitle && aiTier) { tier = aiTier; confidence = 'medium'; }
    else { tier = 2; needsTitle = true; confidence = 'low'; }
  } else if (tier !== 3) {
    confidence = (aiTier === tier) ? 'high' : 'medium';
  } else {
    confidence = 'high';
  }

  // 4) Gate 1 preliminary flag — INDEPENDENT of tier.
  let preliminaryFlag = 'Cleared - Move to Sector Assessment';
  if (gate1.entityInCountry) preliminaryFlag = 'Flag: Legal Entity Conflict';
  else if (gate1.exec) preliminaryFlag = 'Flag: Executive Role';

  const eorCompliant = tier === 1 ? 'Yes' : tier === 3 ? 'No' : 'Pending';
  const screenRequired = (tier === 1 && preliminaryFlag === 'Cleared - Move to Sector Assessment') ? 'No' : 'Yes';

  // Concise single-line verdict (deterministic audit stamp). AI note carries deal prose.
  let verdict = `${tierStr(tier)} — ${sector.name} (via ${resolvedBy})`;
  if (screenOutTrigger) verdict += `; Tier 3 trigger: ${screenOutTrigger}`;
  else if (needsTitle) verdict += `; held pending job title`;
  if (preliminaryFlag !== 'Cleared - Move to Sector Assessment') verdict += `; ${preliminaryFlag}`;

  return {
    tier: tierStr(tier), eorCompliant, screenRequired, preliminaryFlag,
    sectorId: sector.id, sectorName: sector.name, resolvedBy,
    basis: verdict, screenOutTrigger, confidence, needsTitle, unplaceable: false, unrecognizedLabel: false,
  };
}


// Parse AI Compliance Output v4.6 — Rich narrative notes, Insufficient Data is own tier, C-suite/entity checks
// Adds QA correction logic from batch tester:
//   - Unknown industry + Tier 1 → flip to Insufficient Data
//   - Tier 3 + moderate-risk industry + no regulated evidence → flip to Tier 2
//   - Unsafe prompt phrase in notes → flip to Insufficient Data

const PILOT_MODE = false;

const deal = (() => {
  try { return $('Build Full Context').item.json || {}; } catch (e) { return {}; }
})();

const raw = $input.item.json || {};

function stripCodeFence(value) {
  return String(value || '').trim()
    .replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```$/i, '').trim();
}

function parseAiOutput(input) {
  let value = input;
  if (value && typeof value === 'object') {
    if (value.output !== undefined) value = value.output;
    else if (value.text !== undefined) value = value.text;
    else if (value.response !== undefined) value = value.response;
    else if (value.message?.content !== undefined) value = value.message.content;
    else if (value.generations?.[0]?.[0]?.text !== undefined) value = value.generations[0][0].text;
  }
  if (value && typeof value === 'object') return value;
  const text = stripCodeFence(value);
  try { return JSON.parse(text); } catch (e) {
    const start = text.indexOf('{'); const end = text.lastIndexOf('}');
    if (start >= 0 && end > start) return JSON.parse(text.slice(start, end + 1));
    throw e;
  }
}

function clean(value, fallback = '') { return String(value ?? '').trim() || fallback; }
function norm(v) { return clean(v).toLowerCase(); }
function bool(value, fallback = false) {
  if (value === true || value === false) return value;
  const s = clean(value).toLowerCase();
  if (['true','yes','y','1'].includes(s)) return true;
  if (['false','no','n','0'].includes(s)) return false;
  return fallback;
}

function normalizeTierNumber(value) {
  if (typeof value === 'number' && [1,2,3].includes(value)) return value;
  const s = clean(value).toLowerCase();
  if (s === '1' || s.includes('tier 1') || s.includes('allowed')) return 1;
  if (s === '2' || s.includes('tier 2') || s.includes('conditional')) return 2;
  if (s === '3' || s.includes('tier 3') || s.includes('not allowed') || s.includes('blocked')) return 3;
  return null;
}

function normalizeConfidence(value) {
  const s = clean(value).toLowerCase();
  return ['high','medium','low'].includes(s) ? s : 'low';
}

function normalizeEorCompliant(value, routeKey) {
  const s = clean(value);
  if (['Yes','No','N/A','Pending'].includes(s)) return s;
  const lower = s.toLowerCase();
  if (['true','eligible','compliant','allowed'].includes(lower)) return 'Yes';
  if (['false','ineligible','not compliant','not allowed','blocked'].includes(lower)) return 'No';
  if (['pending','review','needs review','conditional'].includes(lower)) return 'Pending';
  if (routeKey === 'tier1') return 'Yes';
  if (routeKey === 'tier3') return 'No';
  return 'Pending';
}

function normalizeComplianceTier(value, routeKey) {
  const s = clean(value);
  if (['Tier 1','Tier 2','Tier 3','Insufficient Data'].includes(s)) return s;
  const n = normalizeTierNumber(s);
  if (n) return `Tier ${n}`;
  if (routeKey === 'tier1') return 'Tier 1';
  if (routeKey === 'tier2') return 'Tier 2';
  if (routeKey === 'tier3') return 'Tier 3';
  return 'Insufficient Data';
}

function normalizeScreenRequired(value, routeKey, hasFlags) {
  const s = clean(value);
  if (['Yes','No'].includes(s)) return s;
  const lower = s.toLowerCase();
  if (['true','required','yes','y','1'].includes(lower)) return 'Yes';
  if (['false','not required','no','n','0'].includes(lower)) return 'No';
  if (routeKey === 'tier1' && !hasFlags) return 'No';
  return 'Yes';
}

function asArray(value) {
  if (Array.isArray(value)) return value.map(v => String(v || '').trim()).filter(Boolean);
  if (!value) return [];
  return [String(value).trim()].filter(Boolean);
}

function firstMeaningful(values) {
  for (const value of values) {
    const s = clean(value);
    if (meaningfulIndustry(s)) return s;
  }
  return '';
}

function companyNameForBasis(deal) {
  if (Array.isArray(deal.companies) && deal.companies.length) {
    return clean(deal.companies[0].name || deal.companies[0].id);
  }
  return clean(deal.companyName);
}

function buildIndustryBasis(deal, ai = {}) {
  const rawDeal = clean(deal.deal_industry || deal.rawDealIndustry || '');
  const rawCompany = firstMeaningful([
    deal.rawCompanyIndustry,
    ...(Array.isArray(deal.companies) ? deal.companies.flatMap(c => [c.industry, c.industry_group, c.naics_label]) : []),
  ]);
  const mappedIndustry = clean(deal.mappedHubSpotIndustry || deal.industryMapping?.mapped_hubspot_industry || deal.industry || ai.industry_used || '');
  const mappedNaics = clean(deal.mappedNaicsCode || deal.industryMapping?.mapped_naics_code || deal.naics_code || '');
  const mappedLabel = clean(deal.mappedIndustryLabel || deal.industryMapping?.mapped_industry_label || '');
  const matchMethod = clean(deal.industryMappingMatchMethod || deal.industryMapping?.match_method || '');
  const companyName = companyNameForBasis(deal);

  if (!meaningfulIndustry(rawDeal) && meaningfulIndustry(rawCompany)) {
    return [
      `Associated company industry: ${rawCompany}${companyName ? ` from ${companyName}` : ''}.`,
      mappedIndustry ? `Mapped industry: ${mappedIndustry}.` : '',
      mappedNaics ? `NAICS: ${mappedNaics}.` : '',
      mappedLabel ? `Industry label: ${mappedLabel}.` : '',
      matchMethod ? `Match method: ${matchMethod}.` : '',
      'Deal industry field was blank.'
    ].filter(Boolean).join(' ');
  }

  if (meaningfulIndustry(rawDeal)) {
    return [
      `Deal industry field: ${rawDeal}.`,
      mappedIndustry && mappedIndustry !== rawDeal ? `Mapped industry: ${mappedIndustry}.` : '',
      mappedNaics ? `NAICS: ${mappedNaics}.` : '',
      mappedLabel ? `Industry label: ${mappedLabel}.` : '',
      matchMethod ? `Match method: ${matchMethod}.` : ''
    ].filter(Boolean).join(' ');
  }

  if (meaningfulIndustry(mappedIndustry)) {
    return [
      `Mapped industry: ${mappedIndustry}.`,
      mappedNaics ? `NAICS: ${mappedNaics}.` : '',
      mappedLabel ? `Industry label: ${mappedLabel}.` : '',
      matchMethod ? `Match method: ${matchMethod}.` : '',
      'No raw deal industry was available.'
    ].filter(Boolean).join(' ');
  }

  if (deal.amplemarket_enriched && clean(deal.amplemarketIndustry)) {
    const ampInd = clean(deal.amplemarketIndustry);
    return [
      `Amplemarket enrichment: ${ampInd}.`,
      mappedIndustry && mappedIndustry !== ampInd ? `Mapped to ${mappedIndustry}.` : '',
      mappedNaics ? `NAICS: ${mappedNaics}.` : '',
      mappedLabel ? `Industry label: ${mappedLabel}.` : '',
      'Deal industry field and associated company industry were both blank.'
    ].filter(Boolean).join(' ');
  }

  return clean(ai.industry_basis || 'Industry unknown.');
}
