function isCsuiteRole(title) {
  return /\b(ceo|coo|cfo|cto|cmo|cpo|cro|chief\s|president|svp|evp|vp\s|vice.?president|managing.?director|executive.?director|head\s+of|founder|co.?founder)\b/i.test(title);
}

function buildDataGaps(deal, ai) {
  const gaps = [];
  const industry = clean(ai.industry_used || deal.mappedHubSpotIndustry || deal.rawDealIndustry || deal.rawCompanyIndustry || '');
  if (!meaningfulIndustry(industry)) {
    gaps.push('No industry data found (deal field and associated company are both blank)');
  }
  const hasTranscript = !!(deal.avomaTranscriptContext || deal.avomaNotesContext);
  const hasRelevantMeetings = (deal.avomaRelevantMeetingCount || 0) > 0;
  if (!hasTranscript && !hasRelevantMeetings) {
    if (deal.avomaSkipped) {
      gaps.push('No call data — Avoma skipped (' + (deal.avomaSkipReason || 'no search signals') + ')');
    } else if (deal.avomaSearchAttempted) {
      gaps.push('No call data — no recent Avoma meetings found');
    } else {
      gaps.push('No call data — Avoma not queried');
    }
  }
  const role = clean((Array.isArray(deal.jobTitles) ? deal.jobTitles[0] : '') || ai.job_title_used || '');
  if (!role) gaps.push('Role not specified in CRM or contacts');
  return gaps;
}

function buildMissingDataNote(deal, ai, gaps) {
  const parts = ['Compliance screen incomplete; additional information needed.'];
  if (gaps.length) parts.push('Missing: ' + gaps.join('; ') + '.');
  if (gaps.some(g => g.toLowerCase().includes('no call'))) {
    parts.push('Call transcript cannot be retrieved without Avoma data — expected if no calls have occurred yet.');
  }
  parts.push('Deal flagged for review. Re-screen will run automatically once the deal is updated.');
  return parts.join(' ');
}

function addContextualNotes(baseNote, deal, ai, routeKey) {
  const extras = [];
  const roleText = clean(ai.job_title_used || (Array.isArray(deal.jobTitles) ? deal.jobTitles[0] : '') || '');
  if (isCsuiteRole(roleText)) {
    extras.push('Role is C-suite / executive (' + roleText + ' — CEO/COO/CFO equivalent): typically a desk-based strategic or management function.');
  }
  const contextText = clean(deal.notesContext || '') + ' ' + clean(deal.avomaNotesContext || '') + ' ' + clean(deal.companyIndustryContext || '');
  if (/\b(legal entity|entity in|entity established|already registered|local entity|own entity|direct employment|existing entity|client entity)\b/i.test(contextText)) {
    extras.push('Note: Client may have a legal entity in the target country — verify whether EOR is required or if direct employment is the appropriate structure.');
  }
  if (!extras.length) return baseNote;
  return [baseNote, ...extras].join(' ');
}
