function genericComplianceNote(value) {
  const s = norm(value);
  return !s ||
    /low-risk and compliant/.test(s) ||
    /industry is low-risk/.test(s) ||
    /eor can proceed as the industry/.test(s) ||
    /no material risk reasons identified/.test(s);
}

function countEntries(text, pattern) {
  const s = clean(text);
  if (!s || s === '(no notes yet)') return 0;
  const matches = s.match(pattern);
  return matches ? matches.length : 0;
}

function buildEvidenceSummary(deal) {
  const parts = [];

  const dealNoteCount = countEntries(deal.notesContext || '', /\[Note \(deal\)/g);
  const companyNoteCount = countEntries(deal.notesContext || '', /\[Note \(company\)/g);
  const emailCount = countEntries(deal.notesContext || '', /\[Note \(email\)/g);
  const unknownNoteCount = Math.max(0, countEntries(deal.notesContext || '', /\[Note/g) - dealNoteCount - companyNoteCount - emailCount);

  if (dealNoteCount) parts.push(`${dealNoteCount} deal note${dealNoteCount > 1 ? 's' : ''}`);
  else parts.push('no deal notes found');
  if (companyNoteCount) parts.push(`${companyNoteCount} company note${companyNoteCount > 1 ? 's' : ''}`);
  if (emailCount) parts.push(`${emailCount} email/activity item${emailCount > 1 ? 's' : ''}`);
  if (unknownNoteCount) parts.push(`${unknownNoteCount} other CRM note${unknownNoteCount > 1 ? 's' : ''}`);

  const companyContext = clean(deal.companyIndustryContext || '');
  if (companyContext && companyContext !== 'No associated company context found.') parts.push('associated company context');
  else parts.push('no associated company context');

  const hasTranscript = !!clean(deal.avomaTranscriptContext);
  const hasAvomaInsights = !!clean(deal.avomaNotesContext);
  const meetingCount = deal.avomaRelevantMeetingCount || 0;
  if (hasTranscript) parts.push(`Avoma transcript reviewed (${meetingCount || 1} meeting${(meetingCount || 1) !== 1 ? 's' : ''})`);
  else if (hasAvomaInsights) parts.push('Avoma meeting notes reviewed, no transcript');
  else if (deal.avomaSkipped) parts.push(`Avoma skipped (${deal.avomaSkipReason || 'no search signals'})`);
  else if (deal.avomaSearchAttempted) parts.push('Avoma searched, no relevant meetings found');
  else parts.push('Avoma not queried');

  const contacts = Array.isArray(deal.contacts) ? deal.contacts : [];
  const titles = Array.isArray(deal.jobTitles) ? deal.jobTitles.filter(Boolean) : [];
  if (titles.length) parts.push(`contact title(s): ${titles.slice(0,3).join(', ')}`);
  else if (contacts.length) parts.push(`${contacts.length} contact${contacts.length > 1 ? 's' : ''} found, no title`);
  else parts.push('no associated contacts');

  const descSignals = [deal.business_goals, deal.hs_next_step, deal.decision_process, deal.decision_criteria, deal.description, deal.deal_description]
    .map(clean).filter(Boolean);
  if (descSignals.length) parts.push('deal description/goals/next steps reviewed');
  else parts.push('no deal description/goals/next steps');

  return parts.join('; ');
}

function buildIndustrySourceStatement(deal, ai, industryBasis) {
  const rawDeal = clean(deal.deal_industry || deal.rawDealIndustry || '');
  const rawCompany = firstMeaningful([
    deal.rawCompanyIndustry,
    ...(Array.isArray(deal.companies) ? deal.companies.flatMap(c => [c.industry, c.industry_group, c.naics_label]) : []),
  ]);
  const mappedIndustry = clean(deal.mappedHubSpotIndustry || deal.industryMapping?.mapped_hubspot_industry || deal.industry || ai.industry_used || '');
  const mappedNaics = clean(deal.mappedNaicsCode || deal.industryMapping?.mapped_naics_code || deal.naics_code || '');
  const mappedLabel = clean(deal.mappedIndustryLabel || deal.industryMapping?.mapped_industry_label || '');
  const matchMethod = clean(deal.industryMappingMatchMethod || deal.industryMapping?.match_method || '');
  const companyName = companyNameForBasis(deal);

  if (meaningfulIndustry(rawDeal)) {
    return `Industry source: deal industry field = ${rawDeal}${mappedIndustry && mappedIndustry !== rawDeal ? `; mapped to ${mappedIndustry}` : ''}${mappedNaics ? ` / NAICS ${mappedNaics}` : ''}${mappedLabel ? ` / ${mappedLabel}` : ''}${matchMethod ? ` (${matchMethod} match)` : ''}.`;
  }
  if (meaningfulIndustry(rawCompany)) {
    return `Industry source: associated company${companyName ? ` ${companyName}` : ''} industry = ${rawCompany}${mappedIndustry ? `; mapped to ${mappedIndustry}` : ''}${mappedNaics ? ` / NAICS ${mappedNaics}` : ''}${mappedLabel ? ` / ${mappedLabel}` : ''}${matchMethod ? ` (${matchMethod} match)` : ''}. Deal industry field was blank.`;
  }
  if (deal.amplemarket_enriched && clean(deal.amplemarketIndustry)) {
    const ampInd = clean(deal.amplemarketIndustry);
    return `Industry source: Amplemarket enrichment → ${ampInd}${mappedIndustry && mappedIndustry !== ampInd ? `; mapped to ${mappedIndustry}` : ''}${mappedNaics ? ` / NAICS ${mappedNaics}` : ''}${mappedLabel ? ` / ${mappedLabel}` : ''}. Deal industry field and associated company industry were both blank.`;
  }
  if (meaningfulIndustry(mappedIndustry)) {
