  }
  return `Industry source: no meaningful deal industry, associated company industry, NAICS mapping, or enrichment industry was available. ${industryBasis || ''}`.trim();
}

function buildInsufficientReasons(deal, ai, dataGaps) {
  const reasons = [];
  const rawDeal = clean(deal.deal_industry || deal.rawDealIndustry || '');
  const rawCompany = firstMeaningful([
