    ...(Array.isArray(deal.companies) ? deal.companies.flatMap(c => [c.industry, c.industry_group, c.naics_label]) : []),
  ]);
  const mappedIndustry = clean(deal.mappedHubSpotIndustry || deal.industryMapping?.mapped_hubspot_industry || deal.industry || ai.industry_used || '');
  const role = clean(ai.job_title_used || (Array.isArray(deal.jobTitles) ? deal.jobTitles[0] : '') || deal.business_goals || deal.hs_next_step || deal.description || '');
  const companyContext = clean(deal.companyIndustryContext || '');
  const notes = clean(deal.notesContext || '');

  if (!meaningfulIndustry(rawDeal) && !meaningfulIndustry(rawCompany) && !meaningfulIndustry(mappedIndustry)) {
    reasons.push('no meaningful industry was found in the deal field, associated company fields, NAICS mapping, or enrichment');
  }
  if (!companyContext || companyContext === 'No associated company context found.') reasons.push('no associated company context was available');
  if (!role) reasons.push('no role, job title, use-case description, goals, or next-step detail was available');
  if (!notes || notes === '(no notes yet)') reasons.push('no usable CRM notes, company notes, email/activity, or prior context was available');
  if (!clean(deal.avomaTranscriptContext) && !clean(deal.avomaNotesContext)) {
    if (deal.avomaSearchAttempted) reasons.push('Avoma was searched but no relevant call notes/transcript were found');
    else if (deal.avomaSkipped) reasons.push(`Avoma was skipped because ${deal.avomaSkipReason || 'no safe search signals were available'}`);
    else reasons.push('Avoma call/transcript evidence was not available');
  }
  for (const gap of (dataGaps || [])) if (gap && !reasons.some(r => r.toLowerCase().includes(String(gap).toLowerCase().slice(0, 20)))) reasons.push(gap);
  return reasons;
}

function buildComplianceNotes(routeKey, hubspotDealProperties, deal, ai, industryBasis, useCaseDescription, recommendedAction, dataGaps) {
  const mappedIndustry = clean(deal.mappedHubSpotIndustry || deal.industryMapping?.mapped_hubspot_industry || deal.industry || ai.industry_used || '');
  const rawDeal = clean(deal.deal_industry || deal.rawDealIndustry || '');
  const rawCompany = firstMeaningful([
    deal.rawCompanyIndustry,
    ...(Array.isArray(deal.companies) ? deal.companies.flatMap(c => [c.industry, c.industry_group, c.naics_label]) : []),
  ]);
  const industryDisplay = clean(ai.industry_used || mappedIndustry || rawDeal || rawCompany || 'unknown');
  const sourceStatement = buildIndustrySourceStatement(deal, ai, industryBasis);
  const evidenceSummary = clean(ai.evidence_reviewed) || buildEvidenceSummary(deal);
  const aiBody = clean(ai.compliance_notes || ai.classification_reason || ai.role_risk_summary || '');
  const riskList = asArray(ai.risk_reasons).join('; ');
  const endSector = clean(ai.end_sector_used);
  const endSectorBasis = clean(ai.end_sector_basis);
  const confidenceText = normalizeConfidence(ai.confidence);

  if (routeKey === 'insufficient') {
    const reasons = buildInsufficientReasons(deal, ai, dataGaps);
    const p1 = `This deal could not be screened — Insufficient Data. ${sourceStatement}`;
    const p2 = `Evidence reviewed: ${evidenceSummary}. Missing/weak basis: ${reasons.length ? reasons.join('; ') : 'the available CRM and call context did not provide enough industry or role evidence to support a tier'}.`;
    const p3 = `Why this result: a compliance tier cannot be assigned without a reliable industry/source basis or a clear role/use-case risk signal. Recommended action: add the company industry, company description/domain, target role/use case, and any relevant notes or call context, then re-run the screen.`;
    return addContextualNotes([p1, p2, p3].join('\n\n'), deal, ai, routeKey);
  }

  if (routeKey === 'tier1') {
    const p1 = `This deal is Tier 1 — EOR can proceed. Industry assessed as ${industryDisplay}. ${sourceStatement}`;
    const p2 = `Evidence reviewed: ${evidenceSummary}. ${endSector ? `End sector used: ${endSector}${endSectorBasis ? ` (${endSectorBasis})` : ''}.` : 'No separate pass-through/end-client sector was required based on the available evidence.'}`;
    const p3 = `Why this tier: ${aiBody || 'the reviewed evidence supports desk-based, non-regulated work.'} The reviewed evidence did not show regulated, licensed, clinical, hazardous, field-based, public-authority, safety-critical, security-cleared, or high-risk end-client-sector signals. Recommended action: ${recommendedAction}.`;
    return addContextualNotes([p1, p2, p3].join('\n\n'), deal, ai, routeKey);
  }

  if (routeKey === 'tier2') {
    const p1 = `This deal is Tier 2 — Compliance review required; EOR may be possible pending review. Industry assessed as ${industryDisplay}. ${sourceStatement}`;
    const p2 = `Evidence reviewed: ${evidenceSummary}. ${endSector ? `End sector used: ${endSector}${endSectorBasis ? ` (${endSectorBasis})` : ''}.` : 'End-client sector was not separately confirmed or was not required for this direct-operating context.'}`;
    const p3 = `Why this tier: ${aiBody || `${industryDisplay} is moderate-risk, regulated-adjacent, operational, ambiguous, or missing role-level detail.`}${riskList ? ` Risk factors: ${riskList}.` : ''} Confidence: ${confidenceText}. Recommended action: ${recommendedAction}.`;
    return addContextualNotes([p1, p2, p3].join('\n\n'), deal, ai, routeKey);
  }

  if (routeKey === 'tier3') {
    const p1 = `This deal is Tier 3 — EOR not permitted. Industry assessed as ${industryDisplay}. ${sourceStatement}`;
    const p2 = `Evidence reviewed: ${evidenceSummary}. ${endSector ? `End sector used: ${endSector}${endSectorBasis ? ` (${endSectorBasis})` : ''}.` : 'No separate pass-through/end-client sector was required based on the available evidence.'}`;
    const p3 = `Why this tier: ${aiBody || 'a specific Tier 3 screen-out or role-based trigger was identified.'}${riskList ? ` Risk factors: ${riskList}.` : ''} Recommended action: ${recommendedAction}.`;
    return addContextualNotes([p1, p2, p3].join('\n\n'), deal, ai, routeKey);
  }

  return addContextualNotes(aiBody || `${hubspotDealProperties.compliance_tier} compliance screen. ${industryBasis}`, deal, ai, routeKey);
}

function meaningfulIndustry(v) {
  const s = norm(v);
  return !!s && !['unknown','not set','n/a','na','none','other','something','generic','null','undefined',''].includes(s);
}

let ai;
try { ai = parseAiOutput(raw); }
catch (e) {
  return [{ json: { ...deal, pilotMode: PILOT_MODE, routeKey: 'error',
    errorMessage: `Could not parse AI compliance output: ${e.message}`, rawAiOutput: raw } }];
}



// Map the deterministic engine result onto this node's tier/routeKey model.
// ── v5.1 MATRIX ENGINE INVOCATION ────────────────────────────────────────────
function __v5_hasTitle(deal, ai){
  if (Array.isArray(deal && deal.jobTitles) && deal.jobTitles.some(t => String(t||'').trim())) return true;
  const t = String((ai && ai.job_title_used) || (deal && deal.primaryTitle) || '').trim();
  if (t) return true;
  const cs = (deal && Array.isArray(deal.contacts)) ? deal.contacts : [];
  return cs.some(c => String(c && c.jobtitle || '').trim());
}
function __v5_entitySignal(deal){
  const ctx = [deal && deal.notesContext, deal && deal.contextBlock, deal && deal.avomaNotesContext,
    deal && deal.avomaTranscriptContext, deal && deal.companyIndustryContext, deal && deal.description,
    deal && deal.business_goals, deal && deal.hs_next_step].map(v => String(v||'')).join(' ');
  return /\b(legal entity|entity in|entity established|already registered|local entity|own entity|existing entity|client entity|has (an |their own )?entity|registered (entity|company|branch|subsidiary) in|own (subsidiary|branch))\b/i.test(ctx);
}
function __v5_execSignal(deal, ai){
  const titles = String((ai && ai.job_title_used) || '') + ' ' +
    ((Array.isArray(deal && deal.jobTitles) ? deal.jobTitles.join(' ') : '')) + ' ' +
    (((deal && deal.contacts) || []).map(c => String(c && c.jobtitle || '')).join(' ')) + ' ' +
    String((deal && deal.primaryTitle) || '');
  return /\b(ceo|coo|cfo|cto|cmo|cpo|cro|chief\s|president|svp|evp|vp\s|vice.?president|managing.?director|executive.?director|head\s+of|founder|co.?founder|country manager|general manager|\bgm\b)\b/i.test(titles);
}
const __naics = String((deal && (deal.naicsCode || deal.mappedNaicsCode || deal.naics_code)) || '');
const atlas = atlasEvaluate({
  aiSector: ai.atlas_sector || '',
  aiIndustry: ai.industry_used || (deal && (deal.industry || deal.mappedHubSpotIndustry)) || '',
  aiTier: (typeof ai.recommended_tier === 'number') ? ai.recommended_tier : (parseInt(ai.recommended_tier,10) || null),
  naics: __naics,
  hasTitle: (ai.has_role_evidence === true) || __v5_hasTitle(deal, ai),
  gate1: {
    exec: (ai.exec_or_fiduciary_title === true) || __v5_execSignal(deal, ai),
    entityInCountry: (ai.client_has_entity_in_country === true) || __v5_entitySignal(deal),
  },
  gate2: {
    entityLicense: ai.requires_entity_license === true,
    individualLicense: ai.individual_license_tied_to_employer === true,
    unionCba: ai.union_or_cba_covered === true,
    sensitiveSecurity: ai.sensitive_data_or_security_cleared === true,
  },
});
// ─────────────────────────────────────────────────────────────────────────────
let tier = atlas.tier === 'Tier 1' ? 1 : atlas.tier === 'Tier 2' ? 2 : atlas.tier === 'Tier 3' ? 3 : null;
let routeKey = atlas.unplaceable ? 'insufficient' : (tier===1?'tier1':tier===2?'tier2':tier===3?'tier3':'insufficient');
if (atlas.unplaceable) { ai.insufficient_data = true; }
let qaFlag = 'OK', qaNotes = '';
if (atlas.unplaceable) { qaFlag='Missing Data'; qaNotes='No Atlas sector could be resolved — add industry/company/role detail and re-screen.'; }
else if (atlas.needsTitle) { qaFlag='Needs Title'; qaNotes='Mixed/regulated sector held at Tier 2 pending a job title or role detail.'; }
else if (atlas.screenOutTrigger) { qaFlag='Tier 3 Screen-out'; qaNotes=atlas.screenOutTrigger; }
else if (atlas.preliminaryFlag !== 'Cleared - Move to Sector Assessment') { qaFlag='Preliminary Flag'; qaNotes=atlas.preliminaryFlag; }
let hasMissingData = atlas.unplaceable || atlas.needsTitle;

const riskReasons = asArray(ai.risk_reasons);
const preliminaryFlags = asArray(ai.preliminary_flags);
const hasFlags = preliminaryFlags.length > 0;

if (routeKey === 'error') {
  return [{ json: { ...deal, pilotMode: PILOT_MODE, routeKey,
    errorMessage: 'AI output did not include a valid tier of 1, 2, or 3.', rawAiOutput: ai } }];
}

const hubspotDealProperties = {
  eor_compliant: normalizeEorCompliant(
    routeKey === 'insufficient' ? 'Pending' : ai.eor_compliant, routeKey
  ),
  compliance_tier: normalizeComplianceTier(
    routeKey === 'insufficient' ? 'Insufficient Data' : (ai.compliance_tier || ai.tier), routeKey
  ),
  compliance_validated_by: clean(ai.compliance_validated_by, 'AI Compliance Checker'),
  eor_compliance_screen_required: normalizeScreenRequired(
    routeKey === 'insufficient' ? 'Yes' : (ai.eor_compliance_screen_required || ai.compliance_review_required),
    routeKey, hasFlags
  ),
};

// ─── EOR PRELIMINARY FLAG (v4.7) ──────────────────────────────────────────
// HubSpot enum values must match EXACTLY:
//   "Cleared - Move to Sector Assessment" | "Flag: Executive Role" | "Flag: Legal Entity Conflict"
function normalizePreliminaryFlag(value) {
  const s = clean(value).toLowerCase();
  if (!s) return '';
  if (s.includes('executive')) return 'Flag: Executive Role';
  if (s.includes('entity')) return 'Flag: Legal Entity Conflict';
  if (s.includes('cleared') || s.includes('sector')) return 'Cleared - Move to Sector Assessment';
  return '';
}

const prelimRoleText = clean(ai.job_title_used || (Array.isArray(deal.jobTitles) ? deal.jobTitles.join(' | ') : '') || '');
const prelimContextText = [deal.notesContext, deal.avomaNotesContext, deal.avomaTranscriptContext, deal.companyIndustryContext, deal.description, deal.business_goals, deal.hs_next_step]
  .map(v => clean(v)).filter(Boolean).join(' ');
const entityConflictSignal = /\b(legal entity|entity in|entity established|already registered|local entity|own entity|direct employment|existing entity|client entity|has (an |their own )?entity|registered (entity|company|branch|subsidiary) in|own (subsidiary|branch))\b/i.test(prelimContextText);
const execRoleSignal = isCsuiteRole(prelimRoleText);

let eorPreliminaryFlag = normalizePreliminaryFlag(ai.eor_preliminary_flag);
let eorPreliminaryFlagBasis = eorPreliminaryFlag ? clean(ai.eor_preliminary_flag_basis, 'AI assessment from reviewed evidence.') : '';

// Deterministic signals override / backfill the AI assessment.
if (entityConflictSignal) {
  eorPreliminaryFlag = 'Flag: Legal Entity Conflict';
  eorPreliminaryFlagBasis = 'CRM notes / call context mention an existing or planned legal entity, local registration, or direct employment in the target country — verify whether EOR is the correct structure before sector assessment.';
} else if (execRoleSignal) {
  eorPreliminaryFlag = 'Flag: Executive Role';
  eorPreliminaryFlagBasis = `Contact/role evidence indicates a C-suite or executive position (${prelimRoleText.slice(0, 120)}) — executive roles need a preliminary review (authority, signatory, permanent-establishment risk) before sector assessment.`;
} else if (!eorPreliminaryFlag) {
  eorPreliminaryFlag = 'Cleared - Move to Sector Assessment';
  eorPreliminaryFlagBasis = 'No executive-role or legal-entity-conflict signals found in contact titles, CRM notes, deal description, or call context.';
}
hubspotDealProperties.eor_preliminary_flag = eorPreliminaryFlag;
// ─────────────────────────────────────────────────────────────────────────────

// v5: deterministic engine is authoritative for tier, EOR status, screen-required, and flag.
hubspotDealProperties.compliance_tier = atlas.tier;
hubspotDealProperties.eor_compliant = atlas.eorCompliant;
hubspotDealProperties.eor_compliance_screen_required = atlas.screenRequired;
hubspotDealProperties.eor_preliminary_flag = atlas.preliminaryFlag;
hubspotDealProperties.compliance_validated_by = 'AI Compliance Checker (v5 matrix)';

const ts = new Date().toISOString();
const portalId = clean(deal.portalId, '20072142');
const dealUrl = deal.dealId ? `https://app.hubspot.com/contacts/${portalId}/deal/${deal.dealId}` : '';

const useCaseDescription = clean(ai.use_case_description, 'Use case not clearly stated in CRM, notes, or Avoma.');
const industryBasis = buildIndustryBasis(deal, ai);
const titleBasis = clean(ai.title_basis, Array.isArray(deal.jobTitles) && deal.jobTitles.length ? deal.jobTitles.join(', ') : 'No associated contacts found.');
const recommendedAction = clean(ai.recommended_action, 'Review with Compliance if deal facts change.');
const confidence = normalizeConfidence(ai.confidence);

const dataGaps = buildDataGaps(deal, ai);
hubspotDealProperties._hasMissingData = hasMissingData;
const complianceNotes = buildComplianceNotes(
  routeKey,
  hubspotDealProperties,
  deal,
  ai,
  industryBasis,
  useCaseDescription,
  recommendedAction,
  dataGaps
).slice(0, 3000);

hubspotDealProperties.compliance_notes = ((clean(ai.compliance_notes) ? clean(ai.compliance_notes)+String.fromCharCode(10,10) : '') + '— ' + atlas.basis + ' · screened ' + ts.slice(0,10)).slice(0,3000);

const auditNote = [
  `[AUTO: Compliance Screen - ${ts}]`,
  `Deal: ${deal.dealname || 'Unknown'} (${deal.dealId || 'unknown'})`,
  dealUrl ? `Deal Link: ${dealUrl}` : '',
  `Stage: ${deal.enteredStageName || deal.dealstage || 'unknown'}`,
  `Result: ${hubspotDealProperties.compliance_tier} | EOR Compliant: ${hubspotDealProperties.eor_compliant} | Confidence: ${confidence}`,
  `Compliance Screen Required: ${hubspotDealProperties.eor_compliance_screen_required}`,
  qaFlag !== 'OK' ? `QA Flag: ${qaFlag}${qaNotes ? ' — ' + qaNotes : ''}` : '',
  `Preliminary Flag: ${eorPreliminaryFlag}${eorPreliminaryFlagBasis ? ' — ' + eorPreliminaryFlagBasis : ''}`,
  hasMissingData && dataGaps && dataGaps.length ? `Data Gaps: ${dataGaps.join(' | ')}` : '',
  '',
  `Compliance Notes: ${complianceNotes}`,
  '',
  `Use Case: ${useCaseDescription}`,
  `Industry Basis: ${industryBasis}`,
  `Title / Duty Basis: ${titleBasis}`,
  '',
  riskReasons.length ? `Risk Reasons:\n${riskReasons.map(r => `- ${r}`).join('\n')}` : 'Risk Reasons: None',
  '',
  preliminaryFlags.length ? `Preliminary Flags:\n${preliminaryFlags.map(f => `- ${f}`).join('\n')}` : 'Preliminary Flags: None',
  '',
  `Recommended Action: ${recommendedAction}`,
  ai.compliance_team_note ? `Compliance Team Note: ${clean(ai.compliance_team_note)}` : '',
].filter(Boolean).join('\n');

const repMessage = ai.rep_message || {};
const fallbackSubject = `[Compliance Screen] ${deal.dealname || 'Deal'} - ${hubspotDealProperties.compliance_tier}`;
let repActionSummary = '';
if (routeKey === 'tier1') {
  repActionSummary = 'EOR can proceed. No compliance action required — continue the deal normally.';
} else if (routeKey === 'tier2') {
  if (hasMissingData && dataGaps && dataGaps.length) {
    repActionSummary = 'COMPLIANCE REVIEW REQUIRED — ADDITIONAL DATA NEEDED.\n\n' +
      'Missing information:\n' + dataGaps.map(g => '• ' + g).join('\n') + '\n\n' +
      'Next steps:\n' +
      '1. Update the deal in HubSpot with any missing fields (industry, target country, job title).\n' +
      '2. Note: Call transcript data requires an Avoma recording — this is expected if no calls have occurred yet.\n' +
      '3. Forward this email to compliance@atlashxm.com with the deal link for manual review.\n' +
      'The compliance screen will re-run automatically when the deal is updated.';
  } else {
    repActionSummary = 'COMPLIANCE REVIEW REQUIRED before progressing this deal.\n\nNext steps:\n1. Do not advance this deal to the next stage yet.\n2. Forward this email to compliance@atlashxm.com with the deal link.\n3. A Health & Safety (H&S) Charter will be required.\n4. An MSA/SOW/EA addendum will be needed before close.\nExpected turnaround: 2–3 business days.';
  }
} else if (routeKey === 'tier3') {
  repActionSummary = 'EOR IS NOT PERMITTED for this deal.\n\nNext steps:\n1. Do NOT progress this deal further.\n2. Contact compliance@atlashxm.com immediately with the deal link.\n3. An alternative employment structure must be confirmed before any further activity.';
}

const fallbackBody = [
  `Hi ${deal.ownerFirstName || 'there'},`,
  '',
  `Compliance screening completed for ${deal.dealname || 'this deal'}.`,
  dealUrl ? `Deal Link: ${dealUrl}` : '',
  '',
  `Result: ${hubspotDealProperties.compliance_tier}`,
  `EOR Compliant: ${hubspotDealProperties.eor_compliant}`,
  `Compliance Screen Required: ${hubspotDealProperties.eor_compliance_screen_required}`,
  `Confidence: ${confidence}`,
  qaFlag !== 'OK' ? `QA Flag: ${qaFlag}${qaNotes ? ' — ' + qaNotes : ''}` : '',
  '',
  `Compliance Notes: ${complianceNotes}`,
  '',
  `Use Case: ${useCaseDescription}`,
  '',
  riskReasons.length ? `Why:\n${riskReasons.map(r => `- ${r}`).join('\n')}` : 'Why: No material risk reasons identified.',
  '',
  `Next Step: ${recommendedAction}`,
  '',
  '─────────────────────────────',
  'WHAT YOU NEED TO DO:',
  repActionSummary,
  '',
  dealUrl ? `Deal Link: ${dealUrl}` : '',
].filter(Boolean).join('\n');

const aiEmailBody = clean(repMessage.body);
const finalEmailBody = aiEmailBody
  ? [aiEmailBody, '', dealUrl ? `Deal Link: ${dealUrl}` : '', '', `Compliance Notes: ${complianceNotes}`].filter(Boolean).join('\n')
  : fallbackBody;

return [{
  json: {
    ...deal,
    pilotMode: PILOT_MODE,
    routeKey, tier, confidence,
    insufficientData: bool(ai.insufficient_data, false),
    qaFlag, qaNotes,
    eorPreliminaryFlag, eorPreliminaryFlagBasis,
    hubspotDealProperties,
    eor_compliant: hubspotDealProperties.eor_compliant,
    compliance_tier: hubspotDealProperties.compliance_tier,
    compliance_validated_by: hubspotDealProperties.compliance_validated_by,
    eor_compliance_screen_required: hubspotDealProperties.eor_compliance_screen_required,
    compliance_notes: complianceNotes,
    complianceNotes,
    dealUrl,
    riskReasons, prelimFlags: preliminaryFlags,
    recommendedAction, useCaseDescription, industryBasis, titleBasis,
    auditNote,
    emailSubject: clean(repMessage.subject, fallbackSubject),
    emailBody: finalEmailBody,
    rawTieringOutput: ai,
    timestamp: ts,
  },
}];

let fallback = {};
try { fallback = $('Build Full Context').item?.json || {}; } catch (_) { fallback = {}; }
const incoming = $input.item.json || {};
const deal = { ...fallback, ...incoming };
let err = 'Unknown error';
try {
  if (typeof deal.errorMessage === 'string') err = deal.errorMessage;
  else if (deal.error && typeof deal.error.message === 'string') err = deal.error.message;
  else if (deal.error && typeof deal.error === 'string') err = deal.error;
} catch (_) { err = 'Unknown error'; }
const ts = new Date().toISOString();
return [{ json: {
  ...deal,
  errorNote: [
    `[AUTO: Compliance Screen ERROR - ${ts}]`,
    `Deal: ${deal.dealname || 'Unknown'} (${deal.dealId || 'unknown'})`,
    `Trigger: ${deal.triggerLabel || 'unknown'}`,
    `Error: ${err}`,
    `Action: Admin notified - manual review required.`
  ].join('\n'),
  timestamp: ts,
  adminSubject: `[COMPLIANCE ERROR] ${deal.dealname || 'Unknown Deal'}`,
  adminBody: [
    'Compliance screening failed.',
    '',
    `Deal: ${deal.dealname || 'Unknown'} (ID: ${deal.dealId || 'unknown'})`,
    `Trigger: ${deal.triggerLabel || 'unknown'}`,
    `Error: ${err}`,
    '',
    `Review manually: https://app.hubspot.com/contacts/REPLACE_WITH_PORTAL_ID/deal/${deal.dealId || ''}`,
    '',
    '---', ts
  ].join('\n')
} }];

