const deal = $('Score Relevant Meetings').item.json || $input.item.json || {};
const meetings = Array.isArray(deal.avomaMeetings) ? deal.avomaMeetings : [];
return meetings.map((meeting, index) => ({
  json: {
    ...deal,
    avomaMeetingIndex: index,
    avomaMeeting: meeting,
    meetingUuid: meeting.meetingUuid || meeting.uuid || '',
    transcriptionUuid: meeting.transcriptionUuid || null,
  }
}));

const meetingItems = $('Prepare Avoma Meeting Fetches').all();
function arr(v) { return Array.isArray(v) ? v : []; }
function clean(v) { return String(v || '').replace(/\s+/g, ' ').trim(); }
function notesToText(insights) {
  const notes = arr(insights.ai_notes);
  return notes.map(n => clean(n.text)).filter(Boolean).join('\n');
}

return $input.all().map((item, index) => {
  const base = (meetingItems[index] && meetingItems[index].json) || {};
  const resp = item.json || {};
  const insights = resp.body || resp;
  const errored = !!(resp.error || resp.detail || (resp.statusCode && Number(resp.statusCode) >= 400));
  return {
    json: {
      ...base,
      avomaInsights: errored ? {} : insights,
      avomaNotesText: errored ? '' : notesToText(insights),
      avomaNotesErrored: errored,
    }
  };
});

const enrichedItems = $('Attach Avoma Notes').all();
const transcriptItems = $input.all();

function arr(v) { return Array.isArray(v) ? v : []; }
function clean(v) { return String(v || '').replace(/\s+/g, ' ').trim(); }
function lineClamp(text, maxChars) {
  const s = String(text || '');
  return s.length > maxChars ? s.slice(0, maxChars) + '\n[truncated]' : s;
}
function transcriptToText(trans) {
  if (!trans || trans.error || trans.detail || (trans.statusCode && Number(trans.statusCode) >= 400)) return '';
  const body = trans.body || trans;
  if (!Array.isArray(body.transcript)) return '';
  const speakerMap = {};
  for (const s of arr(body.speakers)) {
    speakerMap[s.id] = {
      name: s.name || s.email || 'Unknown',
      isRep: s.is_rep === true,
    };
  }
  return body.transcript.map(seg => {
    const sp = speakerMap[seg.speaker_id] || { name: 'Unknown', isRep: false };
    const text = clean(seg.transcript || seg.text || '');
    return text ? `${sp.isRep ? '[REP]' : '[PROSPECT]'} ${sp.name}: ${text}` : '';
  }).filter(Boolean).join('\n');
}

const firstBase = (enrichedItems[0] && enrichedItems[0].json) || $('Score Relevant Meetings').item.json || {};
const meetingsOut = [];
let notesParts = [];
let transcriptParts = [];
let totalNotesChars = 0;
let totalTranscriptChars = 0;
const MAX_NOTES_CHARS = 16000;
const MAX_TRANSCRIPT_CHARS = 32000;

for (let i = 0; i < enrichedItems.length; i++) {
  const base = enrichedItems[i].json || {};
  const meeting = base.avomaMeeting || {};
  const transResp = (transcriptItems[i] && transcriptItems[i].json) || {};
  const notesText = clean(base.avomaNotesText || '');
  const transcriptText = transcriptToText(transResp);
  const header = `[${i + 1}] ${meeting.subject || 'Untitled meeting'} | ${meeting.start_at || 'unknown date'} | score ${meeting.score || 0} | ${(meeting.reasons || []).join(', ') || 'no reasons'}`;

  if (notesText && totalNotesChars < MAX_NOTES_CHARS) {
    const block = `${header}\n${notesText}`;
    const remaining = MAX_NOTES_CHARS - totalNotesChars;
    notesParts.push(lineClamp(block, remaining));
    totalNotesChars += Math.min(block.length, remaining);
  }
  if (transcriptText && totalTranscriptChars < MAX_TRANSCRIPT_CHARS) {
    const block = `${header}\n${transcriptText}`;
    const remaining = MAX_TRANSCRIPT_CHARS - totalTranscriptChars;
    transcriptParts.push(lineClamp(block, remaining));
    totalTranscriptChars += Math.min(block.length, remaining);
  }

  meetingsOut.push({
    ...meeting,
    notesFetched: !!notesText,
    transcriptFetched: !!transcriptText,
    notesErrored: base.avomaNotesErrored === true,
    transcriptionErrored: !!(transResp.error || transResp.detail || (transResp.statusCode && Number(transResp.statusCode) >= 400)),
  });
}

const avomaNotesContext = notesParts.length
  ? `AVOMA MEETING NOTES\n===================\n${notesParts.join('\n\n---\n\n')}`
  : '';
const avomaTranscriptContext = transcriptParts.length
  ? `AVOMA TRANSCRIPTS\n=================\n${transcriptParts.join('\n\n---\n\n')}`
  : '';

return [{ json: {
  ...firstBase,
  avomaMeetings: meetingsOut,
  avomaRelevantMeetingCount: meetingsOut.length,
  hasMeetings: meetingsOut.length > 0,
  meetingCount: firstBase.meetingCount || meetingsOut.length,
  avomaNotesContext,
  avomaTranscriptContext,
  meetingSummary: avomaNotesContext,
  hasTranscript: transcriptParts.length > 0,
  avomaSearchAttempted: true,
  avomaSkipped: false,
  avomaSkipReason: '',
} }];

// v3.9.5 - Process notes and dedupe against normalized deal stage.
// Input should be the HubSpot: Search Notes response.
// This node must run after Normalize Deal Payload, HubSpot: Batch Companies, and HubSpot: Search Notes.

const webhook = $('Parse Webhook').item.json || {};
let dealRaw = {};
try { dealRaw = $('Attach Deal Owner').item.json || {}; }
catch (_) { dealRaw = $('Normalize Deal Payload').item.json || $('Get a deal').item.json || {}; }
const props = dealRaw.flatProperties || dealRaw.properties || {};

function arr(value) {
  return Array.isArray(value) ? value : [];
}

function propValue(value) {
  if (value && typeof value === 'object' && !Array.isArray(value)) {
    if (Object.prototype.hasOwnProperty.call(value, 'value')) return value.value;
    if (Object.prototype.hasOwnProperty.call(value, 'id') && Object.keys(value).length <= 2) return value.id;
  }
  return value;
}

function clean(value) {
  const v = propValue(value);
  return String(v ?? '').trim();
}

function flatten(values) {
  const out = [];
  for (const value of values) {
    if (Array.isArray(value)) out.push(...flatten(value));
    else out.push(value);
  }
  return out;
}

function uniq(values) {
  return [...new Set(flatten(values).map(v => clean(v)).filter(Boolean))];
}

function readCompanyIdsFromDeal(raw, p) {
  const ids = [];

  ids.push(
    raw.companyId,
    raw.company_id,
    raw.associatedCompanyId,
    raw.associatedCompanyIds,
    raw.companyIds,
    raw.hs_primary_associated_company,
    p.companyId,
    p.company_id,
    p.associatedCompanyId,
    p.associatedCompanyIds,
    p.companyIds,
    p.hs_primary_associated_company,
    raw.associations?.associatedCompanyIds,
    raw.associations?.companyIds,
  );

  const associationPaths = [
    raw.associations?.companies?.results,
    raw.associations?.company?.results,
    raw.companies,
  ];

  for (const path of associationPaths) {
    for (const item of arr(path)) {
      if (typeof item === 'string' || typeof item === 'number') {
        ids.push(item);
      } else if (item && typeof item === 'object') {
        ids.push(item.id, item.toObjectId, item.companyId, item.hs_object_id);
      }
    }
  }

  return uniq(ids);
}

let companies = [];
try {
  const companyResp = $('HubSpot: Batch Companies').item.json || {};
  const companyResults = Array.isArray(companyResp.results)
    ? companyResp.results
    : Array.isArray(companyResp.body?.results)
      ? companyResp.body.results
      : [];

  companies = companyResults.map(c => {
    const p = c.properties || {};
    return {
      id: clean(c.id || p.hs_object_id),
      name: clean(p.name || c.name),
      domain: clean(p.domain || c.domain),
      industry: clean(p.industry || c.industry),
      industry_group: clean(p.hs_industry_group || c.hs_industry_group),
      description: clean(p.description || c.description),
      naics_code: clean(p.naics_code || c.naics_code),
      naics_label: clean(p.naics_label || c.naics_label),
    };
  });
} catch (e) {
  companies = [];
}

const companyIds = uniq([
  ...readCompanyIdsFromDeal(dealRaw, props),
  ...companies.map(c => c.id),
]);

const primaryCompany = companies[0] || {};
const companyIndustryContext = companies.length
  ? companies.map(c => [
      c.name ? `Company: ${c.name}` : '',
      c.domain ? `Domain: ${c.domain}` : '',
      c.industry ? `Industry: ${c.industry}` : '',
      c.industry_group ? `Industry group: ${c.industry_group}` : '',
      c.naics_code ? `NAICS: ${c.naics_code}` : '',
      c.naics_label ? `NAICS label: ${c.naics_label}` : '',
      c.description ? `Description: ${c.description}` : '',
    ].filter(Boolean).join(' | ')).join('\n')
  : '';

const dealstage = clean(dealRaw.dealstage || props.dealstage || dealRaw.hs_deal_stage || props.hs_deal_stage || webhook.dealstage);
const stageNameById = {
  '60837713': 'Stage 1',
  '60837715': 'Stage 2',
  '60837716': 'Stage 3',
};

const deal = {
  ...webhook,
  ...dealRaw,
  ...props,

  dealId: clean(
    webhook.dealId ||
    dealRaw.dealId ||
    dealRaw.id ||
    props.hs_object_id
  ),

  dealstage,
  enteredStageName: stageNameById[dealstage] || clean(dealRaw.enteredStageName || props.dealstage_label || dealRaw.dealstage_label || dealstage),

  dealname: clean(dealRaw.dealname || props.dealname || webhook.dealname),
  dealCreatedAt: clean(dealRaw.dealCreatedAt || props.hs_createdate || dealRaw.hs_createdate || webhook.dealCreatedAt),

  rawDealIndustry: clean(dealRaw.rawDealIndustry || props.industry || dealRaw.industry),
  deal_industry: clean(dealRaw.deal_industry || props.industry || dealRaw.industry),
  industry: clean(dealRaw.industry || props.industry),

  countries_onboarding: clean(dealRaw.countries_onboarding || props.countries_onboarding || props.countries_to_be_on_boarded || props.contact_country || dealRaw.contact_country),
  countries_to_be_on_boarded: clean(dealRaw.countries_to_be_on_boarded || props.countries_to_be_on_boarded || props.countries_onboarding || props.contact_country || dealRaw.contact_country),

  companyIds,
  companies,
  companyName: clean(primaryCompany.name || props.company || dealRaw.companyName),
  companyDomains: uniq(companies.map(c => c.domain)),

  hubspot_owner_id: clean(dealRaw.hubspot_owner_id || props.hubspot_owner_id),
  ownerId: clean(dealRaw.ownerId || dealRaw.hubspot_owner_id || props.hubspot_owner_id),
  ownerEmail: clean(dealRaw.ownerEmail || dealRaw.repEmail),
  repEmail: clean(dealRaw.repEmail || dealRaw.ownerEmail),
  ownerFirstName: clean(dealRaw.ownerFirstName),
  ownerLastName: clean(dealRaw.ownerLastName),
  ownerFullName: clean(dealRaw.ownerFullName),

  rawCompanyIndustry: clean(primaryCompany.industry || primaryCompany.industry_group || primaryCompany.naics_label),
  companyIndustryContext: companyIndustryContext || 'No associated company context found.',
};

// v3.9.9: merge deal notes + company notes
function extractNotes(resp) {
  if (!resp) return [];
  return Array.isArray(resp.results)
    ? resp.results
    : Array.isArray(resp.body?.results)
      ? resp.body.results
      : [];
}
let dealNotes = [];
let companyNotes = [];
try { dealNotes = extractNotes($('HubSpot: Search Notes').item.json); } catch (_) { dealNotes = []; }
try { companyNotes = extractNotes($('HubSpot: Search Company Notes').item.json); } catch (_) { companyNotes = []; }
// v4.5: pull recent email activity bodies as additional compliance evidence
let emailItems = [];
try {
  const emailResp = $('HubSpot: Search Emails').item.json;
  emailItems = Array.isArray(emailResp?.results) ? emailResp.results
    : Array.isArray(emailResp?.body?.results) ? emailResp.body.results : [];
} catch (_) { emailItems = []; }
function stripHtml(s){ return clean(s).replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim(); }
const emailNotes = emailItems.map(e => {
  const p = e.properties || {};
  const subject = clean(p.hs_email_subject);
  const text = clean(p.hs_email_text) || stripHtml(p.hs_email_html);
  const ts = clean(p.hs_timestamp);
  if (!subject && !text) return null;
  return { id: e.id, _source: 'email', properties: { hs_note_body: `EMAIL${subject ? ' - ' + subject : ''}: ${text}`.slice(0, 1500), hs_timestamp: ts } };
}).filter(Boolean);
const tagged = [
  ...dealNotes.map(n => ({ ...n, _source: 'deal' })),
  ...companyNotes.map(n => ({ ...n, _source: 'company' })),
  ...emailNotes,
];
// dedupe by note id
const seen = new Set();
const notes = [];
for (const n of tagged) {
  const id = n.id || n.properties?.hs_object_id || JSON.stringify(n.properties?.hs_note_body || '').slice(0, 100);
  if (seen.has(id)) continue;
  seen.add(id);
  notes.push(n);
}

const forceRescreen = !!(deal.forceRescreen);
const alreadyScreened = !forceRescreen && !!dealstage && notes.some(n => {
  const body = clean(n?.properties?.hs_note_body);
  const enteredStageName = clean(deal.enteredStageName);

  return body.includes('[AUTO: Compliance Screen') &&
    (body.includes(`StageEntered: ${dealstage}`) ||
     (!!enteredStageName && body.includes(`StageEntered: ${enteredStageName}`)));
});

let notesContext = '';
let chars = 0;
const noteTimestamps = [];

for (const note of notes) {
  const body = clean(note?.properties?.hs_note_body);
  const timestamp = clean(note?.properties?.hs_timestamp);

  if (timestamp) noteTimestamps.push(timestamp);
  if (!body) continue;

  const source = note._source ? `(${note._source})` : '';
  const line = `[Note ${source} ${timestamp || 'unknown'}]: ${body}\n\n`;
  if (chars + line.length > 8000) break;

  notesContext += line;
  chars += line.length;
}

return [{
  json: {
    ...deal,
    alreadyScreened,
    noteTimestamps,
    notesContext: notesContext || '(no notes yet)',
  }
}];

// v3.9.5 - Normalize HubSpot deal payload shape before stage routing.
// HubSpot/n8n may return properties as { value, timestamp, ... } objects.
// This node creates stable flat fields like dealstage, dealId, companyIds, etc.

const raw = $input.item.json || {};
const webhook = $('Parse Webhook').item.json || {};

function arr(value) {
  return Array.isArray(value) ? value : [];
}

function propValue(value) {
  if (value && typeof value === 'object' && !Array.isArray(value)) {
    if (Object.prototype.hasOwnProperty.call(value, 'value')) return value.value;
    if (Object.prototype.hasOwnProperty.call(value, 'id') && Object.keys(value).length <= 2) return value.id;
  }
  return value;
}

function clean(value) {
  const v = propValue(value);
  return String(v ?? '').trim();
}

function flatten(values) {
  const out = [];
  for (const value of values) {
    if (Array.isArray(value)) out.push(...flatten(value));
    else out.push(value);
  }
  return out;
}

function uniq(values) {
  return [...new Set(flatten(values).map(v => clean(v)).filter(Boolean))];
}

function pick(...values) {
  for (const value of values) {
    const s = clean(value);
    if (s) return s;
  }
  return '';
}

const rawProps = raw.properties || {};
const flatProperties = {};
for (const [key, value] of Object.entries(rawProps)) {
  flatProperties[key] = propValue(value);
}

const associations = raw.associations || {};
const companyIds = uniq([
  raw.companyId,
  raw.company_id,
  raw.associatedCompanyId,
  raw.associatedCompanyIds,
  raw.companyIds,
  raw.hs_primary_associated_company,
  flatProperties.companyId,
  flatProperties.company_id,
  flatProperties.associatedCompanyId,
  flatProperties.associatedCompanyIds,
  flatProperties.companyIds,
  flatProperties.hs_primary_associated_company,
  associations.associatedCompanyIds,
  associations.companyIds,
  arr(associations.companies?.results).map(c => c?.id || c?.toObjectId || c?.companyId),
  arr(associations.company?.results).map(c => c?.id || c?.toObjectId || c?.companyId),
  arr(raw.companies).map(c => typeof c === 'object' ? (c?.id || c?.toObjectId || c?.companyId) : c),
]);

const contactIds = uniq([
  raw.contactId,
  raw.contact_id,
  raw.associatedContactId,
  raw.associatedContactIds,
  raw.contactIds,
  flatProperties.contactId,
  flatProperties.contact_id,
  flatProperties.associatedContactId,
  flatProperties.associatedContactIds,
  flatProperties.contactIds,
  associations.associatedVids,
  associations.contactIds,
  arr(associations.contacts?.results).map(c => c?.id || c?.toObjectId || c?.vid || c?.contactId),
  arr(associations.contact?.results).map(c => c?.id || c?.toObjectId || c?.vid || c?.contactId),
]);

const dealstage = pick(
  raw.dealstage,
  flatProperties.dealstage,
  raw.hs_deal_stage,
  flatProperties.hs_deal_stage,
  raw.hs_deal_stage_id,
  flatProperties.hs_deal_stage_id,
  webhook.dealstage
);

const stageNameById = {
  '60837713': 'Stage 1',
  '60837715': 'Stage 2',
  '60837716': 'Stage 3',
};

return [{
  json: {
    ...webhook,
    ...raw,
    flatProperties,

    dealId: pick(webhook.dealId, raw.dealId, raw.id, flatProperties.hs_object_id),
    dealstage,
    hs_deal_stage: pick(raw.hs_deal_stage, flatProperties.hs_deal_stage),
    enteredStageName: stageNameById[dealstage] || pick(flatProperties.dealstage_label, raw.dealstage_label, dealstage),

    dealname: pick(flatProperties.dealname, raw.dealname, webhook.dealname),
    dealCreatedAt: pick(flatProperties.hs_createdate, raw.hs_createdate, flatProperties.createdate, raw.createdate, webhook.dealCreatedAt),

    rawDealIndustry: pick(flatProperties.industry, raw.industry),
    deal_industry: pick(flatProperties.industry, raw.industry),
    industry: pick(flatProperties.industry, raw.industry),

    countries_onboarding: pick(
      flatProperties.countries_onboarding,
      flatProperties.countries_to_be_on_boarded,
      flatProperties.contact_country,
      raw.countries_onboarding,
      raw.contact_country
    ),
    countries_to_be_on_boarded: pick(
      flatProperties.countries_to_be_on_boarded,
      flatProperties.countries_onboarding,
      flatProperties.contact_country,
      raw.countries_to_be_on_boarded,
      raw.contact_country
    ),

    hubspot_owner_id: pick(raw.hubspot_owner_id, flatProperties.hubspot_owner_id, raw.ownerId, flatProperties.ownerId),
    ownerId: pick(raw.hubspot_owner_id, flatProperties.hubspot_owner_id, raw.ownerId, flatProperties.ownerId),
    ownerEmail: pick(raw.ownerEmail, flatProperties.owner_email, flatProperties.hubspot_owner_email),
    ownerFirstName: pick(raw.ownerFirstName, flatProperties.owner_first_name),
    ownerLastName: pick(raw.ownerLastName, flatProperties.owner_last_name),

    companyIds,
    contactIds,
  }
}];

// Attach Deal Owner
// Purpose: keep the normalized deal payload and add owner/rep email fields from HubSpot owner lookup.
const base = $('Normalize Deal Payload').item.json || {};
const resp = $input.item.json || {};
const body = resp.body || resp;

function clean(value) {
  return String(value ?? '').trim();
}

const ownerId = clean(base.hubspot_owner_id || base.ownerId || body.id || body.ownerId);
const ownerEmail = clean(body.email || base.ownerEmail || base.repEmail);
const ownerFirstName = clean(body.firstName || base.ownerFirstName);
const ownerLastName = clean(body.lastName || base.ownerLastName);

return [{
  json: {
    ...base,
    hubspot_owner_id: ownerId,
    ownerId,
    ownerEmail,
    repEmail: ownerEmail,
    ownerFirstName,
    ownerLastName,
    ownerFullName: [ownerFirstName, ownerLastName].filter(Boolean).join(' '),
    ownerLookupStatus: ownerEmail ? 'resolved' : 'missing_owner_email'
  }
}];

