// Clean Owner + Deal Fields
// Purpose: provide simple readable fields for downstream n8n expressions.
// Examples: {{ $json.Email }}, {{ $json.OwnerName }}, {{ $json.DealUrl }}

const d = $input.item.json || {};

function clean(value) {
  return String(value ?? '').trim();
}

const portalId = clean(d.portalId || '20072142');
const dealId = clean(d.dealId);

const ownerFirstName = clean(d.ownerFirstName);
const ownerLastName = clean(d.ownerLastName);
const ownerName = clean(d.ownerFullName) || [ownerFirstName, ownerLastName].filter(Boolean).join(' ') || 'Deal Owner';
const ownerEmail = clean(d.repEmail || d.ownerEmail);
const dealUrl = dealId ? `https://app.hubspot.com/contacts/${portalId}/deal/${dealId}` : '';

return [
  {
    json: {
      ...d,

      // Simple readable fields for n8n expressions
      Email: ownerEmail,
      OwnerEmail: ownerEmail,
      OwnerName: ownerName,
      OwnerFirstName: ownerFirstName || ownerName.split(' ')[0] || '',
      OwnerLastName: ownerLastName,

      DealId: dealId,
      DealName: clean(d.dealname),
      DealStage: clean(d.enteredStageName || d.dealstage),
      DealUrl: dealUrl,

      CompanyName: clean(d.companyName),
      Industry: clean(d.industry || d.rawDealIndustry),
      Country: clean(d.countries_onboarding || d.countries_to_be_on_boarded),

      // Preserve canonical names too
      repEmail: ownerEmail,
      ownerEmail,
      ownerFullName: ownerName,
      dealUrl,
    },
  },
];

const deal = $('Needs Industry Enrichment?').item.json;
const ampResp = $input.item.json;
function clean(v) { return String(v ?? '').trim(); }
function arr(v) { return Array.isArray(v) ? v : []; }
const body = ampResp.body || ampResp;
const results = arr(body.results).concat(arr(body.data), arr(body.people), arr(body.items), arr(body.prospects));
let ampIndustry = '';
for (const person of results) {
  const co = person.company || person.current_company || person.organization || person.account || {};
  const ind = clean(co.industry || co.industry_name || co.linkedin_industry || co.category || co.sector || (Array.isArray(co.industries) ? co.industries[0] : ''));
  if (ind) { ampIndustry = ind; break; }
}
const existingIndustry = clean(deal.industry) || clean(deal.mappedHubSpotIndustry);
const enrichedIndustry = existingIndustry || ampIndustry;
const wasEnriched = !existingIndustry && !!ampIndustry;
const enrichedMapping = wasEnriched ? {
  ...(deal.industryMapping || {}),
  match_method: 'amplemarket_enrichment',
  mapping_confidence: 'candidate',
  mapped_hubspot_industry: ampIndustry,
  source_files: ['amplemarket'],
} : (deal.industryMapping || {});
return { json: {
  ...deal,
  industry: enrichedIndustry || deal.industry || '',
  rawDealIndustry: enrichedIndustry || deal.rawDealIndustry || '',
  deal_industry: enrichedIndustry || deal.deal_industry || '',
  amplemarketIndustry: ampIndustry,
  amplemarket_enriched: wasEnriched,
  enrichmentNote: wasEnriched ? 'Industry enriched via Amplemarket: ' + ampIndustry : (!existingIndustry && !results.length ? 'Amplemarket returned no results' : 'HubSpot industry kept'),
  industryMapping: enrichedMapping,
}};

