// Attach Contacts — v4.7. Merge batch contact read into the deal payload.
// Populates deal.contacts / deal.jobTitles / deal.contactEmails which were previously never set.
const deal = $('Clean Owner + Deal Fields').item.json || {};
const resp = $input.item.json || {};
const body = resp.body || resp;
const results = Array.isArray(body.results) ? body.results : [];
function clean(v){ return String(v ?? '').trim(); }
const contacts = results.map(c => {
  const p = c.properties || {};
  return {
    id: clean(c.id || p.hs_object_id),
    firstName: clean(p.firstname),
    lastName: clean(p.lastname),
    email: clean(p.email),
    jobtitle: clean(p.jobtitle),
  };
}).filter(c => c.id);
const jobTitles = [...new Set(contacts.map(c => c.jobtitle).filter(Boolean))];
const contactEmails = [...new Set([
  ...(Array.isArray(deal.contactEmails) ? deal.contactEmails : []),
  ...contacts.map(c => c.email).filter(Boolean),
])];
const contactIds = [...new Set([
  ...(Array.isArray(deal.contactIds) ? deal.contactIds : []),
  ...contacts.map(c => c.id),
])];
return [{ json: {
  ...deal,
  contacts,
  jobTitles,
  contactEmails,
  contactIds,
  contactsFetched: contacts.length,
  contactsFetchErrored: !!(resp.error || (resp.statusCode && Number(resp.statusCode) >= 400 && !results.length)),
} }];
